  { key: 'posts.per_page', type: 'integer', default: 10, min: 1, max: 100, scopes: ['site', 'tenant'] },
  { key: 'ui.theme', type: 'enum', default: 'light', values: ['light', 'dark'], autoload: true, scopes: ['site', 'tenant', 'user'] },
