  { key: 'menu.links', type: 'json', default: [], scopes: ['site'] },
  { key: 'smtp.token', type: 'string', default: '', secret: true },
  { key: 'site.slogan', type: 'string', default: '', validate: (v) => (typeof v === 'string' && /<script/i.test(v) ? 'no scripts in the slogan' : null) },
